input.command:
$env:PLANE_API_KEY='REDACTED'
"--- installed uv versions"; Get-ChildItem "$env:LOCALAPPDATA\mise\installs\uv" | Select-Object Name, LastWriteTime | Format-Table -AutoSize | Out-String
"--- running plane-mcp processes"; Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'plane-mcp' } | Select-Object ProcessId, CreationDate, @{n='Cmd';e={$_.CommandLine.Substring(0,[Math]::Min(140,$_.CommandLine.Length))}} | Format-Table -AutoSize | Out-String -Width 220
foreach ($v in @(@{n='UV_SYSTEM_CERTS=1 (script)';e=@{UV_SYSTEM_CERTS='1'}}, @{n='UV_NATIVE_TLS=1';e=@{UV_NATIVE_TLS='1'}})) {
  "--- $($v.n)"
  foreach ($k in $v.e.Keys) { Set-Item "Env:$k" $v.e[$k] }
  $o = '' | & uvx --no-cache --help 2>&1 | Out-Null
  $o = & uvx --refresh-package plane-mcp-server --from plane-mcp-server python -c "print('ok')" 2>&1 | Select-Object -Last 3
  $o | Out-String
  foreach ($k in $v.e.Keys) { Remove-Item "Env:$k" }
}
"--- --system-certs flag"; & uvx --system-certs --refresh-package plane-mcp-server --from plane-mcp-server python -c "print('ok')" 2>&1 | Select-Object -Last 3 | Out-String

$pem = "$env:USERPROFILE\.claude\home-arpa-root-ca.pem"
function T($name, [hashtable]$e, [string[]]$extra) {
  "--- $name"
  foreach ($k in $e.Keys) { Set-Item "Env:$k" $e[$k] }
  & uvx @extra --from plane-mcp-server python -c "print('ok')" 2>&1 | Select-Object -Last 2 | Out-String
  foreach ($k in $e.Keys) { Remove-Item "Env:$k" -ErrorAction SilentlyContinue }
}
T 'script env, cached' @{SSL_CERT_FILE=$pem; UV_SYSTEM_CERTS='1'} @()
T 'script env, refresh' @{SSL_CERT_FILE=$pem; UV_SYSTEM_CERTS='1'} @('--refresh-package','plane-mcp-server')
T 'no SSL_CERT_FILE, refresh' @{UV_SYSTEM_CERTS='1'} @('--refresh-package','plane-mcp-server')
"--- script as-is (5s)"; $j = Start-Job { '' | & pwsh -NoProfile -File "$env:USERPROFILE\.claude\scripts\plane-mcp.ps1" orchestrator 2>&1 }; Wait-Job $j -Timeout 8 | Out-Null; "state: $($j.State)"; Receive-Job $j | Select-Object -First 6 | Out-String; Stop-Job $j; Remove-Job $j -Force
